export const createScene = async function (engine, canvas, BABYLON) {
  const enableExtinction = BABYLON.FrameGraphVolumetricLightingTask.IsSupported(engine, true);

  var scene = new BABYLON.Scene(engine);

  await BABYLON.AppendSceneAsync("https://raw.githubusercontent.com/UN1TOne/3DAsset/master/isometric_bedroom.glb", scene);

  scene.getMeshByName("__root__").scaling.scaleInPlace(0.5);
  const ceiling = scene.getMeshByName("Cube_Material_0").clone();
  ceiling.position = new BABYLON.Vector3(0, 0, 37);

  scene.environmentTexture = BABYLON.CubeTexture.CreateFromPrefilteredData("https://assets.babylonjs.com/textures/night.env", scene);
  scene.environmentIntensity = 0.2;

  scene.createDefaultCamera(true, true, true);

  const camera = scene.activeCamera;
  camera.speed = 0.5;
  camera.wheelPrecision = 10;
  camera.alpha = BABYLON.Tools.ToRadians(143);
  camera.beta = BABYLON.Tools.ToRadians(75);
  camera.radius = 160.44;
  camera.minZ = 0.01;
  camera.upperAlphaLimit = BABYLON.Tools.ToRadians(119.562);
  camera.lowerAlphaLimit = BABYLON.Tools.ToRadians(52.52);
  camera.upperBetaLimit = BABYLON.Tools.ToRadians(103.53);
  camera.lowerBetaLimit = BABYLON.Tools.ToRadians(90.89);

  const hemiLight = new BABYLON.HemisphericLight("hemiLight", new BABYLON.Vector3(0, 1, 0), scene);
  hemiLight.intensity = 0.8;
  hemiLight.diffuse = BABYLON.Color3.FromHexString("#1C1385");

  const light = new BABYLON.DirectionalLight("dirLight", new BABYLON.Vector3(0.1, -0.54, 0.83), scene);
  light.intensity = 0;
  light.position = new BABYLON.Vector3(-6.38, 45.12, -76.25);
  light.shadowMinZ = 0;
  light.shadowMaxZ = 300;
  light.autoUpdateExtends = false;
  light.orthoLeft = -35;
  light.orthoRight = 35;
  light.orthoBottom = -25;
  light.orthoTop = 35;
  light.shadowOrthoScale = 0;

  const isWebGPU = engine.isWebGPU;

  const frameGraph = new BABYLON.FrameGraph(scene, true);

  scene.cameraToUseForPointers = camera;
  scene.frameGraph = frameGraph;

  const samples = 4;

  const colorTexture = frameGraph.textureManager.createRenderTargetTexture("color", {
    size: { width: 100, height: 100 },
    options: {
      createMipMaps: false,
      types: [BABYLON.Constants.TEXTURETYPE_HALF_FLOAT],
      formats: [BABYLON.Constants.TEXTUREFORMAT_RGBA],
      samples,
      useSRGBBuffers: [false],
      labels: ["color"],
    },
    sizeIsPercentage: true,
  });

  const lightingVolumeTexture = frameGraph.textureManager.createRenderTargetTexture("lightingVolume", {
    size: { width: 100, height: 100 },
    options: {
      createMipMaps: false,
      types: [BABYLON.Constants.TEXTURETYPE_HALF_FLOAT],
      formats: [BABYLON.Constants.TEXTUREFORMAT_RGBA],
      samples: 1,
      useSRGBBuffers: [false],
      labels: ["lightingVolume"],
    },
    sizeIsPercentage: true,
  });

  const depthTexture = frameGraph.textureManager.createRenderTargetTexture("depth", {
    size: { width: 100, height: 100 },
    options: {
      createMipMaps: false,
      types: [BABYLON.Constants.TEXTURETYPE_UNSIGNED_BYTE],
      formats: [BABYLON.Constants.TEXTUREFORMAT_DEPTH32_FLOAT],
      samples,
      useSRGBBuffers: [false],
      labels: ["depth"],
    },
    sizeIsPercentage: true,
  });

  const clearTask = new BABYLON.FrameGraphClearTextureTask("clear", frameGraph);

  clearTask.clearColor = true;
  clearTask.clearDepth = true;
  clearTask.targetTexture = colorTexture;
  clearTask.depthTexture = depthTexture;
  clearTask.convertColorToLinearSpace = true;

  frameGraph.addTask(clearTask);

  const rlist = {
    meshes: scene.meshes.slice(0),
    particleSystems: [],
  };

  const rlistShadowCaster = {
    meshes: rlist.meshes.slice(0),
    particleSystems: [],
  };

  const shadowGeneratorTask = new BABYLON.FrameGraphShadowGeneratorTask("shadows", frameGraph);

  shadowGeneratorTask.objectList = rlistShadowCaster;
  shadowGeneratorTask.light = light;
  shadowGeneratorTask.camera = camera;
  shadowGeneratorTask.mapSize = isWebGPU ? 2048 : 1024;
  shadowGeneratorTask.filter = BABYLON.ShadowGenerator.FILTER_NONE;

  frameGraph.addTask(shadowGeneratorTask);

  const renderTask = new BABYLON.FrameGraphObjectRendererTask("renderObjects", frameGraph, scene);

  renderTask.targetTexture = clearTask.outputTexture;
  renderTask.depthTexture = clearTask.outputDepthTexture;
  renderTask.objectList = rlist;
  renderTask.camera = camera;
  renderTask.disableImageProcessing = true;
  renderTask.shadowGenerators = [shadowGeneratorTask];
  renderTask.isMainObjectRenderer = true;
  renderTask.resolveMSAADepth = true;

  frameGraph.addTask(renderTask);

  const lightingVolumeTask = new BABYLON.FrameGraphLightingVolumeTask("lightingVolume", frameGraph);

  lightingVolumeTask.shadowGenerator = shadowGeneratorTask;

  const lightVolume = lightingVolumeTask.lightingVolume;

  lightVolume.frequency = isWebGPU ? 1 : 4;
  lightVolume.tesselation = isWebGPU ? 1024 : 256;

  frameGraph.addTask(lightingVolumeTask);

  const volumetricLightingTask = new BABYLON.FrameGraphVolumetricLightingTask("volumetricLighting", frameGraph, enableExtinction);

  volumetricLightingTask.targetTexture = renderTask.outputTexture;
  volumetricLightingTask.depthTexture = renderTask.outputDepthTexture;
  volumetricLightingTask.camera = camera;
  volumetricLightingTask.lightingVolumeMesh = lightingVolumeTask.outputMeshLightingVolume;
  volumetricLightingTask.light = light;
  volumetricLightingTask.lightingVolumeTexture = lightingVolumeTexture;
  if (enableExtinction) {
    volumetricLightingTask.lightPower = new BABYLON.Color3(0.19, 0.11, 0);
    volumetricLightingTask.extinction = new BABYLON.Vector3(0.01, 0.01, 0.03);
  } else {
    volumetricLightingTask.lightPower = new BABYLON.Color3(0.42, 0.36, 0.88);
  }
  volumetricLightingTask.phaseG = 0.05;

  frameGraph.addTask(volumetricLightingTask);

  const guiTask = new BABYLON.GUI.FrameGraphGUITask("gui", frameGraph);

  guiTask.targetTexture = volumetricLightingTask.outputTexture;

  frameGraph.addTask(guiTask);

  const imageProcessing = new BABYLON.FrameGraphImageProcessingTask("imgProcessing", frameGraph);

  imageProcessing.sourceTexture = guiTask.outputTexture;
  imageProcessing.targetTexture = BABYLON.backbufferColorTextureHandle;

  frameGraph.addTask(imageProcessing);

  engine.onResizeObservable.add(async () => {
    await frameGraph.buildAsync();
  });

  await frameGraph.buildAsync();

  const resolveIfReady = (resolve) => {
    engine.beginFrame();
    scene.frameGraph?.execute();
    engine.endFrame();

    const checkReady = () => {
      if (!lightVolume || (lightVolume.isReady() && !lightVolume.firstUpdate)) {
        resolve(scene);
      } else {
        lightVolume.update(true);
        setTimeout(checkReady, 16);
      }
    };

    checkReady();
  };

  return new Promise((resolve) => {
    scene.executeWhenReady(() => {
      resolveIfReady(resolve);
    });
  });
};
